2efbdd4aa93d98154629fa1afb9dd7f7:
query rosterQuery(
  $mnumber: String!
  $subject: String!
  $number: Int!
  $suffix: String
  $section: String!
  $startTerm: String!
  $startYear: Int!
) {
  instructor(mnumber: $mnumber) {
    courses_taught(subject: $subject, number: $number, suffix: $suffix, section: $section, startTerm: $startTerm, endTerm: $startTerm, startYear: $startYear, endYear: $startYear) {
      course {
        subject
        number
        suffix
        title
      }
      course_section
      crn
      term {
        code
        description
      }
      students {
        mnumber
        student {
          first_name
          middle_name
          last_name
          suffix
          email
          programs {
            program {
              code
            }
          }
          academic_info(term: $startTerm, year: $startYear) {
            overall_gpa
            overall_earned_hours
            overall_quality_points
          }
        }
        final_grade
        midterm_grade
        registration_status {
          code
          description
        }
        instructional_method {
          code
          description
        }
        last_attendance
      }
    }
  }
}

6d4ec4709e9a8f6e93c520316a1fade1:
query rosterInfoCardQuery {
  getCurrentYearTerm {
    year
    term {
      code
      description
    }
  }
}

a0924b725005f27654fa7eabe939f33d:
query termSelectorQuery(
  $mnumber: String!
) {
  instructor(mnumber: $mnumber) {
    courses_taught {
      year
      term {
        description
        code
      }
      total_students
      total_credit_hours
    }
  }
}

a8861c7baccd59abce29ad5816a6f982:
query courseSelectorQuery(
  $mnumber: String!
  $term: String!
  $year: Int!
) {
  instructor(mnumber: $mnumber) {
    courses_taught(startTerm: $term, startYear: $year, endTerm: $term, endYear: $year) {
      course {
        subject
        number
        suffix
        title
      }
      course_section
      crn
      total_students
      total_credit_hours
      credit_hour
    }
  }
}
